import { createRoot } from "react-dom/client";
import { Assets } from "pixi.js";

import { App } from "./ui/App.js";

import "@game-ui/styles/tokens.css";
import "@styles/main.css";

Assets.loader.parsers.push({
	name: "audio-passthrough",
	test: (url: string) => /\.(m4a|mp3|webm|ogg|wav)$/i.test(url),
	load: async (url: string) => url
});
// Initialise asset system at module scope
// manifest.json is auto-generated by assetpack (npm run assets:build).
Assets.init({
	basePath: "./assets",
	manifest: "manifest.json"
}).catch(console.error);

const root = document.getElementById("root");
if (!root) throw new Error("Missing #root element");

createRoot(root).render(<App />);
